"""Nov14 acceptance recovery: real rendered user journeys, synthetic private fixtures, no external writes."""
import importlib.util,unittest,json,os,copy
from pathlib import Path
spec=importlib.util.spec_from_file_location('prior',Path(__file__).with_name('qa-consolidated.py'));base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
OUT=Path(os.environ.get('ARENA_QA_ARTIFACTS','var/recovery'));OUT.mkdir(parents=True,exist_ok=True)
class Recovery(base.Consolidated):
 def setUp(self):super().setUp();self.page.set_default_timeout(10000)
 def test_recovery_01_fresh_and_repeat_asset_delivery_and_four_pillars(self):
  p=self.page;pending=set();p.on('request',lambda r:pending.add(r.url));p.on('requestfinished',lambda r:pending.discard(r.url));p.on('requestfailed',lambda r:pending.discard(r.url))
  for width,height in [(1440,900),(810,1080),(390,844)]:
   p.set_viewport_size({'width':width,'height':height})
   for path in ['/','/sports/lacrosse','/sports/swimming','/sports/basketball','/sports/volleyball','/','/recruiting','/locked-in-demo','/']:
    response=p.goto(base.base.BASE+path);self.assertEqual(response.status,200);self.wait_asset_idle(path,width,pending);self.assertFalse(p.locator('#asset-health').is_visible());self.assertTrue(p.evaluate('Array.from(document.styleSheets).filter(s=>s.href).every(s=>s.cssRules.length>0)'));self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'),path+str(width));nav=p.get_by_role('navigation',name='Primary navigation',exact=True);self.assertEqual(nav.locator('a').all_text_contents(),['Profile','SIEM','Recruiting','LockedIn']);self.assertTrue(all(a.bounding_box()['height']>=44 for a in nav.locator('a').all()))
  self.assertIsNone(self.state())
 def wait_asset_idle(self,path,width,pending):
  try:self.page.wait_for_load_state('networkidle')
  except Exception:
   (OUT/('asset-timeout-'+base.base.ENGINE+'.json')).write_text(json.dumps({'path':path,'width':width,'pending':list(pending),'document':self.page.evaluate('()=>({ready:document.readyState,styles:[...document.styleSheets].map(s=>s.href),images:[...document.images].map(i=>({src:i.currentSrc,complete:i.complete,width:i.naturalWidth}))})')},indent=2)+'\n');raise
 def test_recovery_02_stylesheet_failure_recovery_preserves_records(self):
  self.basic();before=self.state();p=self.page;p.route('**/assets/style.css*',lambda r:r.abort());p.goto(base.base.BASE+'/');p.wait_for_selector('#asset-health:not([hidden])');self.assertIn('styles could not load',p.locator('#asset-health').inner_text());self.assertEqual(p.locator('#asset-health').evaluate('(e)=>getComputedStyle(e).backgroundColor'),'rgb(255, 244, 219)');p.unroute('**/assets/style.css*');p.get_by_role('button',name='Retry page assets',exact=True).click();p.wait_for_selector('#asset-health[hidden]',state='attached');self.assertTrue(p.evaluate('document.querySelector("link[rel=stylesheet]").sheet!==null'));self.assertEqual(self.state(),before)
 def test_recovery_03_intentional_guided_onboarding_all_sports_without_recruiting(self):
  p=self.page;ids=[]
  for sport in ['lacrosse','volleyball','basketball','swimming']:
   p.goto(base.base.BASE+'/build?new=1&guided=1');w=p.locator('#athlete-journey');w.wait_for();w.get_by_role('button',name=sport.capitalize(),exact=True).click();w.get_by_label('Search club or Add Your Own',exact=True).fill('Synthetic family club');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Program or team',exact=True).fill('Synthetic team');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Season label',exact=True).fill('Family season');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_role('button',name='Youth',exact=True).click();w.get_by_label('Age group / division',exact=True).fill('U16');p.get_by_role('button',name='Next →',exact=True).click();w.get_by_label('Athlete name',exact=True).fill('Recovery '+sport);w.get_by_label('I am the parent / guardian managing this athlete',exact=True).check();w.locator('.development-choices input').first.check();p.get_by_role('button',name='Next →',exact=True).click();w.get_by_role('button',name='Skip for now — view profile',exact=True).click();w.get_by_role('button',name='Save athlete profile',exact=True).click();p.wait_for_selector('#show-tryouts');profile=self.state()['profiles'][-1];ids.append(profile['id']);self.assertEqual(profile['sport'],sport);self.assertEqual(profile['programTeam'],'Synthetic team');self.assertEqual(len(profile['trainingInterests']),1);self.assertIn(profile['trainingInterests'][0],p.locator('#overview').inner_text());self.assertEqual(profile['goals'],'');self.assertNotIn('recruiting',profile['modules'])
  self.assertEqual(len(set(ids)),4);self.assertEqual(len(self.state()['profiles']),4)
 def add_event(self,title,kind='game',start='2026-11-20',time=''):
  p=self.page;self.nav('Schedule');p.get_by_role('button',name='Add Game/Meet/Tournament',exact=True).click();p.locator('#plan-title').fill(title);p.locator('#plan-kind').select_option(kind);p.locator('#plan-start').fill(start)
  if time:p.locator('#plan-time').fill(time)
  self.assertFalse(p.locator('#plan-end').is_visible());self.assertFalse(p.locator('#plan-until').is_visible());self.assertEqual(p.locator('#plan-repeat').input_value(),'none');p.get_by_role('button',name='Add to schedule',exact=True).click();p.locator('#schedule-list h3').filter(has_text=title).first.wait_for();return self.state()['profiles'][-1]['plans'][-1]['id']
 def test_recovery_04_recurring_and_one_time_competition_stats_and_family_link(self):
  athlete=self.basic();p=self.page;self.nav('Schedule');p.get_by_role('button',name='Add Recurring Practice',exact=True).click();p.locator('#plan-title').fill('Recovery practice');p.locator('#plan-start').fill('2026-11-16');p.locator('#plan-until').fill('2026-11-30');p.locator('[name=plan-days][value="1"]').check();p.locator('[name=plan-days][value="3"]').check();p.locator('#plan-note').fill('Synthetic gym');p.get_by_role('button',name='Add to schedule',exact=True).click();p.wait_for_selector('#schedule-list article');self.assertEqual(p.locator('#schedule-list article').count(),5);game=self.add_event('Recovery game',time='17:00');self.assertEqual(self.state()['profiles'][0]['plans'][-1]['endTime'],'18:00');self.nav('Stats');self.assertEqual(p.locator('#record-event option').count(),2);p.get_by_role('button',name='Log Stats',exact=True).click();p.locator('#record-event').select_option(game);p.locator('#metric-Goals').fill('2');p.get_by_role('button',name='Save game / meet record',exact=True).click();p.wait_for_selector('#stats .record');self.assertEqual(self.state()['profiles'][0]['records'][0]['eventRef'],game);before=self.state();p.goto(base.base.BASE+'/my-ap?scenario=local&section=calendar');p.wait_for_selector('#platform-calendar');p.get_by_label('Calendar date',exact=True).fill('2026-11-20');p.get_by_label('Calendar date',exact=True).press('Tab');p.wait_for_selector('.ap-activity');text=p.locator('#platform-calendar').inner_text();self.assertIn('Recovery game',text);self.assertIn('Recovery practice',text);self.assertNotIn('Rivera',text);self.assertEqual(self.state(),before);self.assertEqual(self.state()['active'],athlete)
 def test_recovery_05_nested_races_matches_keep_independent_competition_records(self):
  for sport,kind in [('swimming','meet'),('volleyball','tournament')]:
   self.basic(sport);p=self.page;event=self.add_event('Recovery '+kind,kind);p.evaluate('''({event})=>{const s=JSON.parse(localStorage.getItem('arenaPathway.v2')),a=s.profiles.find(p=>p.id===s.active);a.plans.find(p=>p.id===event).sessions=[{id:'one',name:'First competition',dayOffset:0},{id:'two',name:'Second competition',dayOffset:0}];localStorage.setItem('arenaPathway.v2',JSON.stringify(s));}''',{'event':event});p.reload();p.wait_for_selector('#show-tryouts',state='attached');self.nav('Stats');options=p.locator('#record-event option').all_text_contents();self.assertEqual(len(options),3);self.assertIn('First competition',' '.join(options));self.assertIn('Second competition',' '.join(options));p.get_by_role('button',name='Log Stats',exact=True).click();p.locator('#record-event').select_option(event+'#one');p.locator('#stats input[type=number]').first.fill('40' if sport=='swimming' else '3');p.get_by_role('button',name='Save game / meet record',exact=True).click();p.wait_for_selector('#stats .record');self.assertEqual(self.state()['profiles'][-1]['records'][0]['eventRef'],event+'#one')
 def test_recovery_06_three_stage_recruiting_explicit_selection_card_approval_revocation(self):
  athlete=self.basic();p=self.page;game=self.add_event('Chosen competition');p.evaluate('''({game})=>{const s=JSON.parse(localStorage.getItem('arenaPathway.v2')),a=s.profiles[0];a.ageYears=16;a.ageReviewedAt=new Date().toISOString();a.records=[{id:'chosen-result',eventRef:game,metrics:{Goals:2},achievement:'Synthetic recorded result'},{id:'practice-result',eventRef:'practice',metrics:{Goals:99}}];a.plans.push({id:'practice',name:'Private practice',kind:'practice',start:'2026-11-20'});localStorage.setItem('arenaPathway.v2',JSON.stringify(s));}''',{'game':game});p.goto(base.base.BASE+'/recruiting');p.wait_for_selector('#recruiting-profile-builder');nav=p.get_by_role('navigation',name='Recruiting journey',exact=True);self.assertEqual(nav.locator('button').count(),3);self.assertGreater(p.locator('.research-results article').count(),0);nav.get_by_role('button',name='2 · Build athlete information',exact=True).click();p.wait_for_selector('[data-builder-host] #recruiting-profile-builder');self.assertEqual(p.locator('[data-selection]:checked').count(),0);self.assertNotIn('Private practice',p.locator('#recruiting-profile-builder').inner_text());p.locator('#recruiting-rules').check();p.wait_for_selector('#recruiting-profile-builder');p.get_by_text('Edit athlete and academic information',exact=True).click();p.get_by_label('Graduation year',exact=True).fill('2028');p.get_by_label('High school',exact=True).fill('Synthetic school');p.get_by_label('About Me / player overview',exact=True).fill('Synthetic athlete story');p.get_by_role('button',name='Save athlete information',exact=True).click();p.wait_for_selector('#recruiting-profile-builder');
  for label in ['Include athlete name','Include graduation year','Include primary position / event','Include club / team','Include high school','Include About Me','Include upcoming events','Include stats','Include achievements']:p.get_by_label(label,exact=True).check()
  p.locator('[data-selection="eventRefs:'+game+'"]').check();p.locator('[data-selection="recordIds:chosen-result"]').check();nav=p.get_by_role('navigation',name='Recruiting journey',exact=True);nav.get_by_role('button',name='3 · Build and preview',exact=True).click();card=p.get_by_role('article',name='Coach-facing local athlete card',exact=True);card.wait_for();self.assertIn('Casey Demo',card.inner_text());self.assertIn('2028',card.inner_text());self.assertIn('Synthetic school',card.inner_text());self.assertIn('Goals: 2',card.inner_text());self.assertNotIn('99',card.inner_text());self.assertNotIn('Private practice',card.inner_text());self.assertFalse(self.state()['profiles'][0]['recruiting'].get('parentApproved',False));p.get_by_role('button',name='Parent approve local preview',exact=True).click();self.assertTrue(self.state()['profiles'][0]['recruiting']['parentApproved']);p.get_by_role('button',name='Revoke preview approval',exact=True).click();self.assertFalse(self.state()['profiles'][0]['recruiting']['parentApproved']);self.assertEqual(self.state()['active'],athlete);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules']);self.assertEqual(len(self.state()['profiles'][0]['records']),2)
 def test_recovery_07_feed_is_single_snapshot_renderer_with_sport_controls(self):
  p=self.page
  for sport in ['lacrosse','volleyball','basketball','swimming']:
   self.basic(sport);self.nav('My Feed');self.follow('news');self.assertFalse(p.locator('#media').is_visible());self.assertGreater(p.locator('#my-feed .editorial-card').count(),0);p.wait_for_selector('#my-feed .news-cover img');self.assertGreater(p.locator('#my-feed .news-cover img').count(),0);self.assertTrue(all('/assets/photos/' in img.get_attribute('src') for img in p.locator('#my-feed .news-cover img').all()));self.assertTrue(all('not article imagery' in c.inner_text() and sport in c.inner_text().lower() for c in p.locator('#my-feed .news-cover figcaption').all()));self.assertIn('snapshot',p.locator('#my-feed').inner_text());self.assertTrue(all(sport in c.inner_text().lower() for c in p.locator('#my-feed .editorial-fallback').all()));chips=p.locator('#my-feed .source-chips button');self.assertGreater(chips.count(),1);chips.nth(1).click();self.assertGreater(p.locator('#my-feed .editorial-card').count(),0);self.nav('Development');self.follow('development');self.assertEqual(p.locator('#camps iframe,#camps video').count(),0)
 def test_recovery_08_parent_tactical_navigation_siem_and_locked_independence(self):
  athlete=self.basic();before=self.state();p=self.page;p.goto(base.base.BASE+'/my-pathway?view=family');p.wait_for_selector('.family-athlete-card');self.assertEqual(p.locator('#parent-workspace-nav a').all_text_contents(),['Players','Recruiting','Network/Messaging','Discover','Calendar','Saved']);p.get_by_role('link',name='View Athlete',exact=False).click();p.wait_for_selector('#profile-nav');self.assertEqual(p.locator('#profile-nav a').all_text_contents(),['Profile','Schedule','Stats','Media','Recruiting']);p.goto(base.base.BASE+'/locked-in-demo');self.assertEqual(p.locator('#lockedin-external-demo').get_attribute('href'),'https://soccercenter.org/locked-in/index.html');p.goto(base.base.BASE+'/my-ap');p.wait_for_selector('.ap-feed');p.get_by_role('button',name='Start Guided Tour',exact=True).click();p.wait_for_selector('#siem-tour[open]');p.get_by_role('button',name='Skip',exact=True).click();self.assertEqual(self.state(),before);self.assertEqual(self.state()['active'],athlete)
